// Slack import (#1179), desktop: the page reached from Groups, the dry run of the northwind fixture
// (real `pollis-import` output in fixtures/slack-import-preview.json, regenerated by
// fixtures/gen_import_previews.py), archived channels only on request, applying it into a new group in
// Slack's order with email invites to the people who already have accounts, and a second run that adds
// nothing and invites nobody twice. A page, never a dialog.

import { readFileSync } from "node:fs";
import path from "node:path";
import { test, expect, type Page } from "./lib/zero-loss";
import { skinAgnosticTest } from "./lib/skins";

// The importer is Ana, the workspace's owner; Cho already has a Pollis account.
const ME = { id: "u_me", email: "slack-import-ana@pollis.test", username: "ana" };
const PREVIEW = JSON.parse(readFileSync(path.join(__dirname, "fixtures", "slack-import-preview.json"), "utf8"));
const EXPORT = PREVIEW.path as string;
const ACCOUNTS = ["slack-import-cho@pollis.test"];

const SKINS = ["terminal", "modern"] as const;
type Skin = (typeof SKINS)[number];

interface Opts {
  background?: string;
  picked?: boolean;
  extra?: Record<string, unknown>;
}

function preload(skin: Skin, { background, picked = true, extra = {} }: Opts) {
  return {
    session: ME,
    profile: { id: ME.id, username: ME.username },
    groups: [],
    channels: {},
    dmChannels: [],
    openPaths: picked ? [EXPORT] : [],
    slackImport: { preview: PREVIEW, accounts: ACCOUNTS },
    preferences: { skin, ...(background ? { background_color: background } : {}) },
    ...extra,
  };
}

async function boot(page: Page, skin: Skin, opts: Opts = {}) {
  await page.addInitScript((data) => {
    (window as unknown as Record<string, unknown>).__POLLIS_PRELOAD__ = data;
  }, preload(skin, opts));
  await page.goto("/");
  await expect(page.getByTestId("app-ready")).toBeAttached();
}

/** Groups → Import from Slack, the way a person gets there. */
async function openImport(page: Page) {
  await page.getByTestId("sidebar").getByTestId("sidebar-row-groups").click();
  await page.getByTestId("menu-item-import-slack").click();
  await expect(page.getByTestId("slack-import-page")).toBeVisible();
}

async function readExport(page: Page) {
  await page.getByTestId("import-choose-zip").click();
  await expect(page.getByTestId("import-plan")).toBeVisible();
}

const SHOTS = process.env.POLLIS_SHOTS;

async function shot(page: Page, name: string, fullPage = true) {
  if (!SHOTS) {
    return;
  }
  await page.screenshot({ path: `${SHOTS}/${name}.png`, fullPage });
}

/** The page's pane, scrolled whole, for a review shot of a long plan. */
async function paneShot(page: Page, name: string) {
  if (!SHOTS) {
    return;
  }
  const pane = page.getByTestId("slack-import-page");
  const height = await pane.evaluate((el) => el.scrollHeight);
  await page.setViewportSize({ width: 1280, height: Math.min(Math.max(height + 120, 800), 6000) });
  await page.screenshot({ path: `${SHOTS}/${name}.png` });
  await page.setViewportSize({ width: 1280, height: 800 });
}

/** The sidebar's channel rows for the imported group, top to bottom. */
async function sidebarChannels(page: Page): Promise<string[]> {
  return page
    .getByTestId("sidebar")
    .locator('[data-testid^="sidebar-group-channels-"] [data-testid^="sidebar-row-"]')
    .evaluateAll((els) =>
      els
        .filter((el) => /^sidebar-row-(channel|voice)-[^-]+$/.test(el.getAttribute("data-testid") ?? ""))
        .map((el) => `#${(el.textContent ?? "").trim().replace(/\s*\d+$/, "")}`),
    );
}

const ORDER = ["#general", "#design", "#eng-backend", "#leadership", "#random", "#watercooler-music"];

for (const skin of SKINS) {
  const agnosticTest = skinAgnosticTest(skin);

  test.describe(`Slack import — ${skin} skin`, () => {
    test("the dry run shows channels, emoji, user groups and who gets invited; nothing is written", async ({ page }) => {
      await boot(page, skin);
      await openImport(page);
      await expect(page.getByTestId("page-title")).toHaveText("Import from Slack");
      await expect(page.getByTestId("import-plan")).toHaveCount(0);
      await readExport(page);

      await expect(page.getByTestId("import-folder")).toContainText(EXPORT);
      await expect(page.getByTestId("import-summary")).toHaveText("Northwind Studio: 6 channels, 6 emoji, 6 people");
      await expect(page.getByTestId("import-target")).toHaveCount(0);

      // One block, no category heading: Slack has none.
      await expect(page.getByTestId("import-plan-block")).toHaveCount(1);
      await expect(page.getByTestId("import-plan-channels")).not.toContainText("Not in a category");
      // Purpose and topic are the description; the private channel is called out.
      await expect(page.getByTestId("import-channel-C02GEN")).toContainText("Company-wide announcements");
      await expect(page.getByTestId("import-channel-C02GEN")).toContainText("Offsite is 12 March");
      await expect(page.getByTestId("import-channel-private-G01LEAD")).toHaveText(
        "Private on Slack. Every group member will see it.",
      );
      // Archived channels are listed as not imported, with the way to bring them.
      await expect(page.getByTestId("import-plan-skipped")).toContainText("launch-2023");
      await expect(page.getByTestId("import-plan-skipped")).toContainText("include archived channels to bring it");
      await expect(page.getByTestId("import-include-archived")).toHaveAttribute("aria-checked", "false");

      // Emoji: the collision is renamed, aliases point at their picture, the impossible ones say why.
      await expect(page.getByTestId("import-emoji-party_parrot")).toContainText(":party_parrot_2:");
      await expect(page.getByTestId("import-emoji-party_parrot")).toContainText("party_parrot was taken");
      await expect(page.getByTestId("import-emoji-ship-it")).toContainText(":ship_it:");
      await expect(page.getByTestId("import-emoji-ship-it")).toContainText("Another name for shipit");
      await expect(page.getByTestId("import-emoji-thumbsup_all")).toContainText("which isn't imported");
      await expect(page.getByTestId("import-emoji-x")).toContainText("No usable name");

      // User groups: listed, not imported (#294).
      await expect(page.getByTestId("import-user-group-S01DES")).toContainText("@design-team");
      await expect(page.getByTestId("import-user-group-S01DES")).toContainText("2 people: cho, Jo Müller");

      // People: an invite plan with emails, never a membership.
      await expect(page.getByTestId("import-plan-people")).toContainText("Slack email belongs to a Pollis account");
      await expect(page.getByTestId("import-person-U01ANA")).toContainText("Make admin");
      await expect(page.getByTestId("import-person-U03CHO")).toContainText("slack-import-cho@pollis.test");
      await expect(page.getByTestId("import-person-U04DEV")).toContainText("No email; invite link only");
      await expect(page.getByTestId("import-plan-people")).not.toContainText("Fin Walsh");
      await expect(page.getByTestId("import-invite-by-email")).toHaveAttribute("aria-checked", "true");
      await expect(page.getByTestId("import-plan-notes")).toContainText("10 messages stay on Slack");

      await expect(page.locator("dialog, [role=dialog], [aria-modal=true]")).toHaveCount(0);
      const groups = await page.evaluate(() => (window as any).__tauriMock.groups.length);
      expect(groups).toBe(0);
    });

    test("import builds the group in Slack's order and invites existing accounts; a re-run adds nothing", async ({
      page,
    }) => {
      await boot(page, skin);
      await openImport(page);
      await readExport(page);
      await page.getByTestId("import-apply").click();

      await expect(page.getByTestId("import-result-title")).toHaveText("Imported into Northwind Studio");
      await expect(page.getByTestId("import-result-counts")).toHaveText("6 channels and 6 emoji added.");
      await expect(page.getByTestId("import-result-invites-invited")).toHaveText(
        "1 person with a Pollis account was invited.",
      );
      await expect(page.getByTestId("import-result-invites-no_account")).toContainText("3 people have no Pollis account yet");
      await expect(page.getByTestId("import-result-invites-no_account")).toContainText("Ben Okafor");
      await expect(page.getByTestId("created-invite-link-url")).toContainText("https://pollis.com/invite/");
      await expect(page.getByTestId("import-result-failures")).toHaveCount(0);
      await expect.poll(() => sidebarChannels(page)).toEqual(ORDER);

      // Second run: the group is the default target; channels and emoji are there, Cho already invited.
      await openImport(page);
      await readExport(page);
      await expect(page.getByTestId("import-target").getByRole("radio", { checked: true })).toContainText(
        "Northwind Studio",
      );
      await expect(page.getByTestId("import-channel-C02GEN")).toContainText("already there");
      await page.getByTestId("import-apply").click();
      await expect(page.getByTestId("import-result-counts")).toHaveText("0 channels and 0 emoji added.");
      await expect(page.getByTestId("import-result-invites-invited")).toHaveCount(0);
      await expect(page.getByTestId("import-result-invites-already_invited")).toHaveText("1 person was already invited.");
      await expect(page.getByTestId("import-result-link-existing")).toBeVisible();
      const groups = await page.evaluate(() => (window as any).__tauriMock.groups.length);
      expect(groups).toBe(1);
    });

    agnosticTest("archived channels come only when asked, marked as archived", async ({ page }) => {
      await boot(page, skin);
      await openImport(page);
      await readExport(page);
      await expect(page.getByTestId("import-channel-C05OLD")).toHaveCount(0);
      await page.getByTestId("import-include-archived").click();
      await expect(page.getByTestId("import-include-archived")).toHaveAttribute("aria-checked", "true");
      await expect(page.getByTestId("import-channel-C05OLD")).toContainText("Archived on Slack");
      await expect(page.getByTestId("import-channel-private-G02HIRE")).toBeVisible();
      await expect(page.getByTestId("import-summary")).toHaveText("Northwind Studio: 8 channels, 6 emoji, 6 people");
      await page.getByTestId("import-apply").click();
      await expect(page.getByTestId("import-result-counts")).toHaveText("8 channels and 6 emoji added.");
    });

    agnosticTest("with invites off, nobody is invited", async ({ page }) => {
      await boot(page, skin);
      await openImport(page);
      await readExport(page);
      await page.getByTestId("import-invite-by-email").click();
      await expect(page.getByTestId("import-invite-by-email")).toHaveAttribute("aria-checked", "false");
      await page.getByTestId("import-apply").click();
      await expect(page.getByTestId("import-result")).toBeVisible();
      await expect(page.getByTestId("import-result-invites")).toHaveCount(0);
    });

    agnosticTest("an unpacked folder works too; a failed import says so and can be retried", async ({ page }) => {
      await boot(page, skin);
      await openImport(page);
      await page.evaluate(() => {
        (window as any).__POLLIS_PRELOAD__.slackImport.failApply = "network unreachable";
      });
      await page.getByTestId("import-choose-folder").click();
      await expect(page.getByTestId("import-plan")).toBeVisible();
      await page.getByTestId("import-apply").click();
      await expect(page.getByTestId("import-error")).toHaveText("Import failed: network unreachable");
      await expect(page.getByTestId("import-apply")).toBeEnabled();
    });

    agnosticTest("the invite sheet copies as CSV with emails", async ({ page }) => {
      await boot(page, skin);
      await openImport(page);
      await readExport(page);
      await page.getByTestId("import-copy-sheet").click();
      await expect(page.getByTestId("import-copy-sheet")).toHaveAttribute("data-copy-state", "copied");
      const copied = await page.evaluate(() => (window as any).__tauriMock.clipboard as string);
      expect(copied.split("\n")[0]).toBe("username,display_name,email,pollis_role,slack_roles,channels,messages");
      expect(copied).toContain("cho,cho,slack-import-cho@pollis.test,member");
      expect(copied).not.toContain("github");
    });

    test("review shots, light and dark", async ({ page }) => {
      test.skip(!SHOTS, "screenshots only");
      for (const [tone, background] of [
        ["dark", undefined],
        ["light", "#f4efe6"],
      ] as const) {
        await page.goto("about:blank");
        await boot(page, skin, { background });
        await openImport(page);
        await shot(page, `slack-import-${skin}-${tone}-empty`, false);
        await readExport(page);
        await paneShot(page, `slack-import-${skin}-${tone}-plan`);
        await page.getByTestId("import-apply").click();
        await expect(page.getByTestId("import-result")).toBeVisible();
        await shot(page, `slack-import-${skin}-${tone}-done`, false);
      }
    });
  });
}
